"use strict";

// RWF-023's canonical reproducer, kept as small as a reproducer can be.
//
// There is no conditional export here, no `process.env` branch, and no
// second candidate for the module's value -- deliberately. Every finding
// from RWF-014 through RWF-022 is about which export WRITE is
// authoritative; this one is about whether the analyzer believes a
// computed class-element KEY executes at all. Stripping the export
// machinery out proves the two are orthogonal: this module is a false
// NOT_AFFECTED before RWF-023 even though nothing about its exports is
// ambiguous.
//
// Runtime, on every single load:
//
//   module evaluation reaches the class definition
//     -> ClassDefinitionEvaluation evaluates the element's computed key
//        -> key() runs
//           -> danger.explode() runs
//
// The method BODY is never entered. Only the KEY runs. See
// fixtures/computed-class-key-module-load-reachability-ground-truth/ for
// the real-node, asserted proof of both halves.
const danger = require("./danger");

function key() {
  danger.explode("from-computed-key");
  return "x";
}

class C {
  [key()]() {}
}

module.exports = C;
